#!/usr/bin/env python3
"""Render frozen scorer outputs; no decisions or gold are changed."""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1];s=json.loads((R/'results/summary.json').read_text());m=json.loads((R/'results/predictions.metadata.json').read_text());f=json.loads((R/'freeze_manifest.json').read_text())
def seconds(x):return 'unavailable' if x is None else f'{x:.3f} s'
def rate(x):return f"{x['numerator']}/{x['denominator']} ({x['rate']*100:.1f}%)" if x['rate'] is not None else f"{x['numerator']}/{x['denominator']} (undefined)"
lines=['# German multi-document precedence: finite-set results','','## Main results','',f"- Both fields exact: {rate(s['case_metrics']['all_fields_exact'])}",f"- Source choice: {rate(s['case_metrics']['source'])}",f"- Determination: {rate(s['case_metrics']['determination'])}",f"- Correct field decisions: {rate(s['case_metrics']['all_field_decisions'])}",'','## Source selection and clarification','']
for group in ['source_metrics','clarification_metrics']:
 for k,v in s[group].items():lines.append(f'- {k}: {rate(v)}')
lines+=['',f"- Field-pair inconsistencies: {rate(s['consistency']['field_pair_inconsistent_with_visible_rules'])}",'','This inconsistency rule allows an uncertain source with a definite answer whenever all plausible sources agree. The nine controls are explicitly scored separately. A wrong source is not evidence of a unique psychological failure mechanism.','','## Domain and precedence strata','']
for group in ['domain','stratum']:
 for k,v in s['strata'][group].items():lines.append(f"- {group} / {k}: exact {rate(v['all_fields_exact'])}; source {rate(v['source_correct'])}; determination {rate(v['determination_correct'])}; invalid/missing {v['invalid_or_missing']}")
t=s['technical'];lines+=['','## Execution and integrity','',f"- Recorded {t['recorded_predictions']}/48; valid {t['valid_cases']}/48; missing {t['missing_predictions']}; invalid existing {t['invalid_existing_predictions']}",f"- Input tokens: {t['input_tokens_min']}–{t['input_tokens_max']}; exact full/cap equality enforced before and during inference",f"- Forward time: median {seconds(t['forward_seconds_median'])}; interpolated p95 {seconds(t['forward_seconds_p95'])}; sum {seconds(t['forward_seconds_total'])}",f"- Maximum observed scored-case process RSS: {t['peak_observed_rss_bytes']} bytes",f"- Native load time: {m.get('load_seconds')} s; run status: {m.get('status')}",f"- Frozen before inference: {f['frozen_at_utc']}; native run started: {m['started_at']}",f"- Model revision: {m['revision']}",'- CPU NF4 backbone; original BF16 joint head and output embeddings; six threads; batch one; cap2048','- Unrelated warmup and post-run first-case probe excluded from metrics','- Every error and all native option scores remain available in results/errors.jsonl and results/predictions.jsonl','','## Interpretation limits','','These are 48 purposefully AI-authored and separately AI-reviewed cases, not human-expert validation or a representative customer sample. Sixteen templates are reused across three domains; twelve domain×stratum families are not independent clusters. Domain/template/family strata remain in the machine-readable summary. No population interval or significance estimate is claimed.','','The task selects one complete rule and a bounded outcome. It does not test composing partial clauses, generated German answer quality, real contractual interpretation or customer actions. Eighteen yes, eighteen no and twelve material clarification cases are deliberately balanced; nine more have ambiguous source but a definite answer. Document IDs and positions are balanced across unique-source outcomes; no matched order-swap intervention occurred, so causal order robustness is not established.','','Marginal native option scores are not calibrated or joint probabilities. This is an experimental CPU NF4 result, without GPU/native-precision claims. Different earlier schemas and datasets are not pooled or treated as a before/after model improvement. Private environment diagnostics are omitted from the public artifact.']
(R/'REPORT.md').write_text('\n'.join(lines)+'\n')
errors=[json.loads(x) for x in (R/'results/errors.jsonl').read_text().splitlines() if x.strip()];out=['# All non-exact or invalid cases','',f'{len(errors)} cases. Gold remains frozen; no post-outcome relabeling.','']
for e in errors:
 c=e['case'];out.extend([f"## {e['id']}: {e['domain']} / {e['subtype']}",'',f"Expected: {e['expected']}",f"Predicted: {e['predicted']}",f"Valid: {e['valid']}; technical issues: {e['technical_issues']}",f"Frozen rationale: {c['rationale']}",'',c['state'],'','All native unrounded probabilities:','',json.dumps(e['probabilities_unrounded'],ensure_ascii=False,indent=2),''])
(R/'ERRORS.md').write_text('\n'.join(out)+'\n')
(R/'README.md').write_text('# German multi-document precedence benchmark\n\n'+f"Both fields exact: {rate(s['case_metrics']['all_fields_exact'])}. Source choice: {rate(s['case_metrics']['source'])}. Determination: {rate(s['case_metrics']['determination'])}.\n\n"+'See REPORT.md, PROTOCOL.md and ERRORS.md; complete native scores are in results/predictions.jsonl. Three fictional documents per case; 48 German cases across banking, insurance and finance. AI-authored and independently AI-reviewed, not human-expert validated or representative.\n\nThe new source/determination schema distinguishes unknown governing source from unknown final answer. All 48 cases and every error are retained. Frozen scientific bytes are preserved under public curation. Reproduce with scripts/reproduce.sh after preparing the exact pinned runtime in a fresh environment; weights are not distributed. Use scripts/verify_export.py to verify a finished public archive.\n')
print(json.dumps({'reports_written':['REPORT.md','ERRORS.md','README.md'],'error_count':len(errors)}))
